use super::*;
#[tokio::test]
#[ignore="validates P2 public IDs, share import, performance and migration with real owned game processes in the existing isolated QA root"]
async fn live_workshop_p2_share_performance_and_migration(){
 let root=PathBuf::from(std::env::var("KXL_AGENT_BUILD_ROOT").unwrap());assert!(root.components().any(|p|p.as_os_str()==".update-qa"));
 let report=read_json(Path::new(&std::env::var("KXL_AGENT_BUILD_REPORT").unwrap())).unwrap();let mut task:Task=serde_json::from_value(report["task"].clone()).unwrap();let c=Core::new(root,Arc::new(|v|{if let Some(stage)=v["stage"].as_str(){println!("{stage}");}})).unwrap();let scoped=scoped_task(&c,&task,Arc::new(AtomicBool::new(false))).unwrap();
 let source=scoped.instance(&task.instance_id).unwrap();let source_config=snapshot::hash(&source.join("kxl.json")).unwrap();let source_files=update::inventory(&source).unwrap();
 let code=share::create(task.plan.as_ref().unwrap()).unwrap();let imported=share::preview(&scoped,&code).await.unwrap();assert_eq!(imported["plan"]["minecraft"],"1.20.1");assert!(code.len()<=8192);println!("PASS: actual catalogue revalidation of decoded share code");
 let account=auth::offline(&scoped,"KXL_P2_QA").unwrap();let account_id=account["id"].as_str().unwrap();
 let performance=performance::analyze(&scoped,&task.instance_id,&json!({"preset":"low","installMods":false})).await.unwrap();assert!(performance["hardware"]["logicalCores"].as_u64().unwrap()>0);
 let applied=performance::apply(&scoped,&mut task,&json!({"preset":"low","installMods":false,"performanceHash":performance["performanceHash"]}),account_id,&json!({})).await.unwrap();assert_eq!(applied["applied"],true);snapshot::restore(&scoped,&task.instance_id,applied["rollbackSnapshotId"].as_str().unwrap()).unwrap();assert_eq!(snapshot::hash(&source.join("kxl.json")).unwrap(),source_config);assert_eq!(update::inventory(&source).unwrap(),source_files);println!("PASS: real performance preset + owned-process launch verification + rollback");
 let migration=migration::plan(&scoped,&task.instance_id,&json!({"target":{"minecraft":"1.20.2","loader":"fabric","loaderVersion":""}})).await.unwrap();assert_eq!(migration["plan"]["target"]["minecraft"],"1.20.2");
 let migrated=migration::apply(&scoped,&mut task,&json!({"plan":migration["plan"],"migrationHash":migration["migrationHash"],"copyConfigs":true,"copySaves":false,"allowUnresolved":true}),account_id,&json!({})).await.unwrap();assert_eq!(migrated["migrated"],true);assert_ne!(migrated["newInstanceId"],task.instance_id);assert_eq!(snapshot::hash(&source.join("kxl.json")).unwrap(),source_config);assert_eq!(update::inventory(&source).unwrap(),source_files);println!("PASS: real migration to a separate compatible instance, source untouched");
 if let Ok(path)=std::env::var("KXL_AGENT_P2_REPORT"){write_json(Path::new(&path),&json!({"passed":true,"shareCatalogueValidated":true,"performance":applied,"migration":migrated,"sourceUnchanged":true,"note":"已实际从 MC 1.20.1 迁移到 1.20.2，未复制存档，无法解析项目按测试确认省略。"})).unwrap();}
}

#[tokio::test]
#[ignore="downloads two real Modrinth pack releases and verifies update/rollback in an isolated QA directory"]
async fn live_workshop_p2_pack_update_and_rollback(){
 let root=PathBuf::from(std::env::var("KXL_AGENT_BUILD_ROOT").unwrap());assert!(root.components().any(|p|p.as_os_str()==".update-qa"));
 let c=Core::new(root,Arc::new(|v|{if v["stage"].as_str().is_some_and(|s|s.contains("验证")){println!("{}",v["stage"]);}})).unwrap();let scoped=policy::scoped(&c,Arc::new(AtomicBool::new(false)),0,policy::now()+1800).unwrap();
 let mut settings=engine::defaults();settings["memory"]=json!(4096);let original=if let Ok(id)=std::env::var("KXL_AGENT_P2_UPDATE_INSTANCE"){let root=scoped.instance(&id).unwrap();read_json(&root.join("kxl.json")).unwrap()}else{packs::install_modrinth(&scoped,&json!({"project":"tx2cXhmh","versionId":"Xih4Whr9","name":"工坊更新隔离验证","settings":settings})).await.unwrap()};let id=original["id"].as_str().unwrap();let root=scoped.instance(id).unwrap();let old_version=original["packSource"]["versionId"].clone();assert_eq!(old_version,"Xih4Whr9");
 std::fs::create_dir_all(root.join("config")).unwrap();std::fs::write(root.join("config/kxl-qa-preserve.json"),b"{\"user\":true}").unwrap();std::fs::create_dir_all(root.join("saves/kxl-qa-world")).unwrap();std::fs::write(root.join("saves/kxl-qa-world/level.dat"),b"world-sentinel").unwrap();let baseline=update::inventory(&root).unwrap();
 let preview=update::check(&scoped,id).await.unwrap();assert_eq!(preview["preview"]["available"],true);assert_eq!(preview["preview"]["candidate"]["versionId"],"aMEJmzxM");assert!(preview["preview"]["differences"]["removed"].as_array().is_some_and(|a|!a.is_empty()));println!("PASS: real compatible release, validated archive and file diff");
 let plan=plan::parse(json!({"version":1,"name":"隔离更新验证","minecraft":"1.20.1","loader":{"type":"fabric","version":"0.15.6"},"memoryMb":4096})).unwrap();let mut task=draft(&scoped,"default",plan,true).unwrap();task.instance_id=id.into();task.confirmed_hash=task.plan_hash.clone();task.status="done".into();let account=auth::offline(&scoped,"KXL_Update_QA").unwrap();let updated=update::apply(&scoped,&mut task,&json!({"updateHash":preview["updateHash"]}),account["id"].as_str().unwrap(),&json!({})).await.unwrap();assert_eq!(updated["packSource"]["versionId"],"aMEJmzxM");assert_eq!(std::fs::read(root.join("config/kxl-qa-preserve.json")).unwrap(),b"{\"user\":true}");assert_eq!(std::fs::read(root.join("saves/kxl-qa-world/level.dat")).unwrap(),b"world-sentinel");
 task.results.insert("pack_update_apply".into(),updated.clone());state::save(&scoped,&mut task,"done").unwrap();let rollback=advanced::execute(&scoped,&json!({"tool":"pack_update_rollback","taskId":task.id,"planHash":task.plan_hash,"confirmed":true,"args":{}})).await.unwrap();assert_eq!(rollback["restored"],true);let restored=read_json(&root.join("kxl.json")).unwrap();assert_eq!(restored["packSource"]["versionId"],old_version);assert_eq!(update::inventory(&root).unwrap(),baseline);assert_eq!(std::fs::read(root.join("saves/kxl-qa-world/level.dat")).unwrap(),b"world-sentinel");
 if let Ok(path)=std::env::var("KXL_AGENT_P2_UPDATE_REPORT"){write_json(Path::new(&path),&json!({"passed":true,"sourceBefore":old_version,"sourceAfter":updated["packSource"]["versionId"],"rollback":rollback,"userConfigPreserved":true,"worldPreserved":true,"diff":preview["preview"]["differences"],"verification":updated["report"]})).unwrap();}
 println!("PASS: actual pack update + game launch + rollback; source, user config and world preserved.");
}
